        missing.is_empty(),
        "the `{mode}` mode links {}, which does not export {} of the items the bindings \
         declare{regenerated} ({}{}): build the bundled C instead",
        so.display(),
        missing.len(),
        missing
            .iter()
            .take(8)
            .cloned()
            .collect::<Vec<_>>()
            .join(", "),
